import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  try { db.prepare('SELECT :a AS a').get({ b: 1 }); } catch (e: any) { console.log(e.code, e.message); }
  const s = db.prepare('SELECT :a AS a');
  s.setAllowUnknownNamedParameters(true);
  console.log(JSON.stringify(s.get({ b: 1 })));
  db.close();
}
